#!/usr/bin/env python3
"""시즌 4 여름 + 막간극 2~4 삽화. out/v06u/<id>_0.png  사용: shots_summer.py [bg|scenes|all|id,...]"""
import subprocess, sys, os, time
SC=os.path.dirname(os.path.abspath(__file__)); A="/home/user/somsom-city/assets/"; AD=A+"day/"; OUT=f"{SC}/out/v06u"; os.makedirs(OUT,exist_ok=True)
PRO,FLASH="gemini-3-pro-image","gemini-3.1-flash-image"; LINE=A+"01_group_lineup.png"
STYLE=("The first reference images are CHARACTER MODEL SHEETS. Every character must match its model sheet EXACTLY: same proportions, face rules, clothes and colors. "
 "The second-to-last reference image is the GROUP LINEUP showing correct relative heights, and the last reference image is the background/style guide: thin uniform dark outlines, flat matte colors, no shading, no gradients, muted pastel palette. "
 "Rules: eyes are small white circles with a black dot pupil always visible; Kkito has NO nose, ears the same pink as the face with only a small light-pink oval at each ear TIP, two tiny curly strands on the forehead; "
 "Migae stands on its rear four legs like a small dog and holds its two front legs up as short arms at the chest, pink bow on the head. Nobody wears glasses except Bookgeo (square black) and Grandma (round gold, on top of her head). No cats, no dogs, no extra animals of any kind. "
 "HEIGHT RULE, measured against Kkito's full height: Boneul 110% (the tallest), Kkito 100%, Ramda's head reaches Kkito's mid-chest (67%), Grandma Lachilchin's head reaches Kkito's hip (57%), Bookgeo on four legs reaches Kkito's knee (47%), Migae reaches just below Kkito's knee (41%) — Migae is never taller than Kkito's knee. "
 "SPECIES: Ramda is a red-brown SQUIRREL with a big bushy upright tail (about as tall as her torso, never larger than her body), never a cat. Grandma Lachilchin is a grey CHINCHILLA: small, round, very fluffy, big round ears, short blunt muzzle, never a cat or dog. Bookgeo is a tortoise with a SHORT THICK neck, never long or giraffe-like, and there is only ever ONE tortoise in a picture. Kkito's two long ears stand straight UP unless she is lying down. Boneul has long sloth arms that must be visible. "
 "The lineup image is ONLY a height reference: draw ONLY the characters named in the scene, each exactly once. "
 "Everyone wears their usual clothes. Vertical 3:4 composition, characters large enough to read their faces, no text, no letters, no watermark.")
KK,MG,BN,RM,BG,LC=("Kkito (pink rabbit, model sheet)","Migae (black pet ant, model sheet)","Boneul (grey sloth, model sheet)","Ramda (squirrel, model sheet)","Bookgeo (tortoise on four legs, model sheet)","Grandma Lachilchin (chinchilla, model sheet)")
B={k:f"{SC}/refs/board_{k}.jpg" for k in ["kkito","migae","boneul","ramda","bookgeo","lachilchin"]}
def bg(name):
    m={"alley_su":AD+"bg_alley_summer.jpg","alley_ht":AD+"bg_alley_heat.jpg","alley_n":AD+"bg_alley_night.jpg","alley_r":AD+"bg_alley_rain.jpg","entry_su":AD+"bg_day_entry_summer.jpg","entry_ht":AD+"bg_day_entry_heat.jpg","entry_n":AD+"bg_day_entry_night.jpg","entry_r":AD+"bg_day_entry_rain.jpg",
       "alley_sp":AD+"bg_alley_spring.jpg","alley_w":AD+"bg_alley_winter.jpg","fest":f"{OUT}/u_fest_bg_0.png"}
    return m.get(name, A+name)
SHOTS=[]; BGS=[]
def scene(id,model,chars,bgname,text,season=""):
    refs=[B[c] for c in chars]+[LINE,bg(bgname)]
    extra=" Bookgeo walks on four legs and always wears his square black glasses; when he holds something he uses exactly ONE arm from under the front of his shell while all four legs stay on the ground." if "bookgeo" in chars else ""
    SHOTS.append((id,model,refs,STYLE+extra+season+"\n\nScene: "+text))
SU=" SUMMER: strong sunlight, deep flat shadows, cicada-season feel."
def recolor(id,src,text):
    BGS.append((id,FLASH,[src],"Recolor and re-dress this EXACT illustration: "+text+" Keep every line, object and the composition identical; change only colors, foliage, sky, weather and small seasonal props. Same flat matte style, thin outlines, no text."))
recolor("bg_alley_summer",A+"bg_alley.png","early summer: the trees are full of deep green leaves, bright blue sky, strong sunlight with a few flat dark shadow shapes on the ground, a small electric fan visible in one window, everything fresh and green.")
recolor("bg_alley_heat",A+"bg_alley.png","peak summer heat wave: very bright washed-out sunlight, pale hot sky, deep dark flat shadows under the trees, heat shimmer implied only by a paler ground, a hand fan lying on the bench, leaves a slightly dusty green.")
recolor("bg_day_entry_summer",A+"bg_day_entry.png","early summer seen through the door/window: deep green leaves, bright blue sky, strong sun, a small electric fan on the floor by the door.")
recolor("bg_day_entry_heat",A+"bg_day_entry.png","heat wave outside: very bright pale sky, washed-out sunlight, deep shadows, a hand fan on the shoe cabinet, a glass of water with ice by the door.")
BGS.append(("u_fest_bg",PRO,[AD+"bg_alley_night.jpg"],"Draw a NEW illustration in EXACTLY the same flat matte style, thin uniform dark outlines and muted pastel night palette as this reference alley: the flat rooftop of a small beige apartment building at night, seen from the back of the rooftop; twelve simple folding chairs in rows facing a large white cloth screen hung on a laundry line between two poles, a small old film projector on a crate at the back, a string of small round lights, a low railing, potted tomato plants in one corner, the dark alley and a second rooftop visible beyond the railing, a starry night sky. No people, no animals, no text."))
