mode=sys.argv[1] if len(sys.argv)>1 else "all"
todo = BGS if mode=="bg" else SHOTS if mode=="scenes" else BGS+SHOTS if mode=="all" else [s for s in BGS+SHOTS if s[0] in set(mode.split(","))]
for id,model,refs,prompt in todo:
    if os.path.exists(f"{OUT}/{id}_0.png"): print("skip",id,flush=True); continue
    missing=[r for r in refs if not os.path.exists(r)]
    if missing: print("MISSING REF",id,missing,flush=True); continue
    open(f"{OUT}/{id}.prompt.txt","w").write(prompt)
    env=dict(os.environ,NB_MODEL=model,NB_AR="3:4",NB_SIZE="1K"); t=time.time()
    for a in range(3):
        r=subprocess.run([sys.executable,f"{SC}/gen.py",f"{OUT}/{id}","1",*refs],stdin=open(f"{OUT}/{id}.prompt.txt"),env=env,capture_output=True,text=True)
        print(id,model.split("-")[2],r.stdout.strip()[-90:],f"({time.time()-t:.0f}s)",flush=True)
        if os.path.exists(f"{OUT}/{id}_0.png"): break
        time.sleep(5)
print("DONE",flush=True)
